parameters.query:
SELECT 
    (SELECT json_agg(cliente_id) FROM public.cliente_tb) AS clientes_ids,
    (SELECT json_agg(veiculo_id) FROM public.veiculo_tb) AS veiculos_ids;

parameters.jsCode:
const clientes_ids = $input.first().json.clientes_ids;
const veiculos_ids = $input.first().json.veiculos_ids;

const destinos_portos_br = [
    "Porto de Santos - SP",
    "Porto de Paranaguá - PR",
    "Porto de Itajaí - SC",
    "Porto de Rio Grande - RS",
    "Porto de Suape - PE",
    "Porto de Pecém - CE",
    "Porto de Itaqui - MA",
    "Porto de Chibatão (Manaus) - AM",
    "Porto de Tubarão (Vitória) - ES",
    "Porto de Aratu - BA"
];

const tamanhos_container = ["20ft", "40ft", "40ft HC"];

// Funções auxiliares para sorteio
const obter_item_aleatorio = (lista) => lista[Math.floor(Math.random() * lista.length)];
const obter_peso_aleatorio = (minimo, maximo) => parseFloat((Math.random() * (maximo - minimo) + minimo).toFixed(2));
const obter_status_aleatorio = () => Math.floor(Math.random() * 6) + 1;

// Retorna o objeto formatado no padrão esperado pelo n8n
return [{
    json: {
        cliente_id: obter_item_aleatorio(clientes_ids),
        veiculo_id: obter_item_aleatorio(veiculos_ids),
        destino: obter_item_aleatorio(destinos_portos_br),
        tamanho_container: obter_item_aleatorio(tamanhos_container),
        peso_total_carga_kg: obter_peso_aleatorio(10000.00, 35000.00),
        status_id: obter_status_aleatorio()
    }
}];

const item = $input.first().json;

// 1. Dados do Gráfico por Estado (Ordenado Decrescente)
const pedidosEstado = (item.pedidos_por_estado || []).sort((a, b) => b.total_pedidos - a.total_pedidos);
const estados = pedidosEstado.map(i => i.destino);
const totalPorEstado = pedidosEstado.map(i => i.total_pedidos);

const configEstado = {
  type: 'bar',
  data: {
    labels: estados,
    datasets: [{
      label: 'Pedidos', // Legenda reativada
      backgroundColor: '#0d6efd',
      borderRadius: 6,
      data: totalPorEstado
    }]
  },
  options: {
    plugins: {
      legend: { 
        display: true, // Habilita a legenda
        position: 'top',
        labels: { font: { family: 'Arial', size: 12, weight: 'bold' } }
      },
      datalabels: {
        anchor: 'end',
        align: 'top',
        color: '#0d6efd',
        font: { weight: 'bold', size: 12 }
      }
    },
    scales: {
      x: { grid: { display: false } },
      y: { grid: { color: '#f0f0f0' }, beginAtZero: true }
    }
  }
};

// 2. Dados do Gráfico de Status (Ordenado Decrescente)
const pedidosStatus = (item.total_por_status || []).sort((a, b) => b.total - a.total);
const statusLabels = pedidosStatus.map(i => i.nome_status);
const totalPorStatus = pedidosStatus.map(i => i.total);

const configStatus = {
  type: 'bar',
  data: {
    labels: statusLabels,
    datasets: [{
      label: 'Total', // Legenda reativada
      backgroundColor: '#20c997',
      borderRadius: 6,
      data: totalPorStatus
    }]
  },
  options: {
    plugins: {
      legend: { 
        display: true, // Habilita a legenda
        position: 'top',
        labels: { font: { family: 'Arial', size: 12, weight: 'bold' } }
      },
      datalabels: {
        anchor: 'end',
        align: 'top',
        color: '#20c997',
        font: { weight: 'bold', size: 12 }
      }
    },
    scales: {
      x: { grid: { display: false } },
      y: { grid: { color: '#f0f0f0' }, beginAtZero: true }
    }
  }
};

// URLs com gráficos grandes e com legendas ativas
return [{
  json: {
    ...item,
    url_grafico_estado: `https://quickchart.io/chart?bkg=white&w=600&h=280&c=${encodeURIComponent(JSON.stringify(configEstado))}`,
    url_grafico_status: `https://quickchart.io/chart?bkg=white&w=600&h=280&c=${encodeURIComponent(JSON.stringify(configStatus))}`
  }
}];

const item = $input.first().json;

// 1. Tratamento do Total de Pedidos Atrasados
const totalAtrasados = item.total_pedidos_atrasados || 0;

// 2. Montagem do Gráfico QuickChart em Azul
const dadosGrafico = (item.grafico_atrasados_estado || []).sort((a, b) => b.total_atrasados - a.total_atrasados);
const estados = dadosGrafico.map(i => i.destino);
const totais = dadosGrafico.map(i => i.total_atrasados);

const configGrafico = {
  type: 'bar',
  data: {
    labels: estados,
    datasets: [{
      label: 'Atrasos',
      backgroundColor: '#0d6efd', // Azul corporativo
      borderRadius: 6,
      data: totais
    }]
  },
  options: {
    plugins: {
      legend: { 
        display: true,
        position: 'top',
        labels: { font: { family: 'Arial', size: 12, weight: 'bold' } }
      },
      datalabels: {
        anchor: 'end',
        align: 'top',
        color: '#0d6efd', // Números em azul
        font: { weight: 'bold', size: 12 }
      }
    },
    scales: {
      x: { grid: { display: false } },
      y: { grid: { color: '#f0f0f0' }, beginAtZero: true }
    }
  }
};

// 3. Montagem Dinâmica do HTML da Tabela
const listaPedidos = item.tabela_pedidos_atrasados || [];
let linhasTabelaHtml = '';

if (listaPedidos.length === 0) {
  linhasTabelaHtml = `
    <tr>
      <td colspan="5" style="padding: 12px; text-align: center; color: #28a745; font-weight: bold;">
        Nenhum pedido atrasado no momento! 🎉
      </td>
    </tr>`;
} else {
  linhasTabelaHtml = listaPedidos.map((pedido, index) => {
    const bgCor = index % 2 === 0 ? '#ffffff' : '#f8f9fa';
    return `<tr style="background-color: ${bgCor}; border-bottom: 1px solid #e9ecef;"><td style="padding: 10px 12px; font-weight: bold; color: #333;">#${pedido.pedido_id}</td><td style="padding: 10px 12px; color: #495057;">${pedido.razao_social}</td><td style="padding: 10px 12px; color: #495057; text-align: center;">${pedido.destino}</td><td style="padding: 10px 12px; text-align: center; color: #495057;">${pedido.tamanho_container || 'N/A'}</td><td style="padding: 10px 12px; text-align: center; color: #dc3545; font-weight: 500;">${pedido.data_criacao}</td></tr>`;
  }).join('');
}

// 4. Retorno Estruturado para o n8n
return [{
  json: {
    ...item,
    total_pedidos_atrasados: totalAtrasados,
    url_grafico_atrasados: `https://quickchart.io/chart?bkg=white&w=600&h=280&c=${encodeURIComponent(JSON.stringify(configGrafico))}`,
    tabela_pedidos_html: linhasTabelaHtml
  }
}];
